          "ನೀವು ಪರಭಕ್ಷಕಗಳನ್ನು ಕೊಂದಾಗ, ಕೀಟಗಳು ಬಲಿಷ್ಠವಾಗಿ ಹಿಂತಿರುಗುತ್ತವೆ ಮತ್ತು ರಾಸಾಯನಿಕ ಪ್ರತಿರೋಧವನ್ನು ಬೆಳೆಸಿಕೊಳ್ಳುತ್ತವೆ, ನಿಮಗೆ ಇನ್ನೂ ಬಲಿಷ್ಠ ವಿಷಗಳನ್ನು ಖರೀದಿಸುವಂತೆ ಒತ್ತಾಯಿಸುತ್ತವೆ.",
