          "சரியான உரம் தயாரிக்க, 30:1 C:N விகிதத்தை இலக்காகக் கொள்ளுங்கள். கார்பன் அதிகமாக இருந்தால் (வைக்கோல், மரம்), சிதைவு நிற்கும். நைட்ரஜன் அதிகமாக இருந்தால் (பச்சை புல், புதிய சாணம்), குவியல் துர்நாற்றம் வீசி ஊட்டச்சத்துக்களை இழக்கும்.",
          "உலர்ந்த மஞ்சள் பொருட்களை ஈரமான பச்சை சாணத்துடன் அடுக்குவது இந்த விகிதத்தை இயற்கையாகவே சமநிலைப்படுத்தும்.",
