          "72 மணி நேரத்திற்குள், உங்கள் குவியல் 55°C–65°C ஆக சூடாக வேண்டும். இது சூரியனால் அல்ல; இது பில்லியன் கணக்கான நுண்ணுயிரிகள் உயிர்த்தொகுதியை உண்ணும் வெப்பம்.",
