          "வாசனை மூல சாணத்திலிருந்து இனிப்பு-புளிப்பு, இனிமையான நொதித்த வாசனையாக மாறும்—இட்லி மாவு அல்லது ஈஸ்ட் போல. திரவம் துர்நாற்றம் வீசினால், அதற்கு போதுமான காற்றோட்டம் கிடைக்கவில்லை.",
