export const LIBRARY_CONTENT: Partial<Record<Locale, LocaleOverrides>> = {
  hi, kn, ta, te, ml, mr, bn, pa,
};

/** Returns `book` with any available `locale` overrides merged in; falls back to English field-by-field. */
export function getLocalizedBook(book: Book, locale: Locale): Book {
  const override = LIBRARY_CONTENT[locale]?.[book.id];
  if (!override) return book;
  return {
    ...book,
    title: override.title ?? book.title,
    subtitle: override.subtitle ?? book.subtitle,
    description: override.description ?? book.description,
    pages: book.pages.map((page, i) => {
      const pageOverride = override.pages?.[i];
      if (!pageOverride) return page;
      return {
        ...page,
        header: pageOverride.header ?? page.header,
        title: pageOverride.title ?? page.title,
        content: pageOverride.content ?? page.content,
        bullets: pageOverride.bullets ?? page.bullets,
        tip: pageOverride.tip ?? page.tip,
        quote: pageOverride.quote ?? page.quote,
      };
    }),
  };
}
